mapper.select:
SELECT r.hypervisor_id, r.status, r.availability_zone,
       r.total_vcpu, r.reserved_vcpu, r.allocated_vcpu,
       r.total_memory_gb, r.reserved_memory_gb, r.allocated_memory_gb,
       r.total_gpu, r.reserved_gpu, r.allocated_gpu, r.resource_version
FROM hypervisor_resource r
JOIN hypervisor_host h ON h.id = r.hypervisor_id
WHERE r.status = 'ACTIVE'
  AND h.hypervisor_status = 'ACTIVE'
  AND r.available_vcpu >= #{vcpus}
  AND r.available_memory_gb >= #{memoryGb}
  AND r.available_gpu >= #{gpuCount}

  AND r.availability_zone = #{availabilityZone}


  AND h.region_id = #{regionId}


  AND h.hypervisor_type = #{hypervisorType}

ORDER BY r.hypervisor_id
LIMIT #{limit}
